// Helper functions
export function getStateBySlug(slug: string): StateData | undefined {
  return statesData.find(s => s.slug === slug);
}

export function getCityBySlug(stateSlug: string, citySlug: string): CityData | undefined {
  const state = getStateBySlug(stateSlug);
  return state?.cities.find(c => c.slug === citySlug);
}

export function getTopCities(limit: number = 20): (CityData & { stateName: string; stateSlug: string; stateAbbr: string })[] {
  const allCities: (CityData & { stateName: string; stateSlug: string; stateAbbr: string })[] = [];
  for (const state of statesData) {
    for (const city of state.cities) {
      allCities.push({ ...city, stateName: state.name, stateSlug: state.slug, stateAbbr: state.abbreviation });
    }
  }
  return allCities.sort((a, b) => (b.population || 0) - (a.population || 0)).slice(0, limit);
}

export function getAllCitySlugs(): { stateSlug: string; citySlug: string }[] {
  const slugs: { stateSlug: string; citySlug: string }[] = [];
  for (const state of statesData) {
    for (const city of state.cities) {
      slugs.push({ stateSlug: state.slug, citySlug: city.slug });
    }
  }
  return slugs;
}

